"""MMX116 / HUNT114: the two resource bugs a table fight showed.

  #1  A Golden Sea Pulse was spendable on the very event that generated it, against its own printed
      rule: authority/typed_mechanics/rules_text.json
      foundation.ancient_desolate_sacred_body_v0_2C.generate_golden_sea_pulse --
        "A Pulse generated by an event cannot be spent on that same event."
      ...golden_sea_guard -- "Requires Reaction and 1 Golden Sea Pulse from a prior event. Does not
      permit same-event spending."   ...refuse_heaven_lock -- "...from a prior event".
  #2  A pool at its cap was logged as gained while nothing was gained ("gained 0 Edict Seal; total 1").

Both fixes are inert for anything that does not own the rule: the grant is held only for pools a
``generate`` row can grant, and only inside the event that produced it, and the log line is dropped
only when the recorded gain really is zero.

MMX116f1 kept these two scope checks but moved them onto the public payment seam
(``typed_reactions._holds``) that ``combat/typed_reactions.py`` now asks. Both this file and
``test_mmx116f1_event_scope.py`` use synthetic engine events, not table persistence.
Real persisted service coverage is in ``tests/test_solfmmx116r2_resources.py``.
"""

from pathlib import Path

from combat import typed_reactions
from combat.gate2_runtime_content import AN
from combat.gate4_engine import Gate4ControllerEngine
from combat.gate2_engine import Gate2Engine
from combat.history_feed import format_history_feed
from combat.factory_compiler import compile_character
from tests.test_pressure import FOUNDATION, ME
from tests.test_zones import SHEET

ROOT = Path(__file__).resolve().parents[1]
PULSE = "resource:foundation.golden_sea_pulse"
GUARD = "foundation.ancient_desolate_sacred_body_v0_2C.golden_sea_guard"


def _engine():
    bundle = compile_character({**SHEET, "foundation": FOUNDATION}, actor_id=ME)
    engine = Gate4ControllerEngine(ROOT, match_seed="MMX116", typed_bundles=(bundle,),
                                   roster_setup={"primary_actor_ids": [ME, AN],
                                                 "team_by_actor": {ME: "team:a", AN: "team:b"},
                                                 "starting_positions": {ME: {"x": 3, "y": 6}, AN: {"x": 4, "y": 6}}})
    engine.state.current_slot_index = engine.state.initiative_order.index(AN)
    engine.state.current_actor_id = AN
    return engine


def _hit(engine, damage=10):
    """One damage packet of a hostile attack, in the engine's own order: the reaction window opens and
    answers first, then the damage is committed (which is when a Foundation trigger generates a Pulse)."""
    engine._append_event("REACTION_WINDOW_OPENED", "test:hit", actor_id=AN, target_ids=(ME,),
                         payload={"checkpoint": "DAMAGE_APPLICATION", "pending_damage": damage})
    pending = typed_reactions.on_damage(engine, engine.state.actors[ME], damage, 0, "test:hit", AN)
    engine._append_event("DAMAGE_COMMITTED", "test:hit", actor_id=AN, target_ids=(ME,),
                         payload={"hp_damage": max(0, pending), "temporary_hp_absorbed": 0})
    return pending


def _guard_resolved(engine):
    return any(event.event_type == "REACTION_RESOLVED" and event.source_definition_id == GUARD
               for event in engine.events)


# ----------------------------------------------------------------------------------- #1 same-event spend
def test_a_pulse_generated_by_an_attack_cannot_be_spent_on_that_same_attack():
    engine = _engine()
    me = engine.state.actors[ME]
    assert me.resources[PULSE] == 0

    _hit(engine)  # the first damage packet of one attack: no Pulse exists yet
    assert me.resources[PULSE] == 1, "the hit generated the Pulse"

    _hit(engine)  # the second packet of the SAME attack, in the same act
    assert me.resources[PULSE] == 1, "the Pulse paid for the attack that generated it"
    assert not _guard_resolved(engine), "Golden Sea Guard answered with the Pulse that same attack generated"


def test_the_pulse_is_spendable_once_a_later_act_begins():
    engine = _engine()
    me = engine.state.actors[ME]
    _hit(engine)
    assert me.resources[PULSE] == 1

    engine._append_event("INTENT_ACCEPTED", "test:next_act", actor_id=AN, target_ids=(), payload={})
    assert typed_reactions._holds(engine, me, PULSE, 1), "a prior event's Pulse is spendable again"

    _hit(engine)  # a new attack in a new act
    assert _guard_resolved(engine), "Golden Sea Guard answers later damage with a prior Pulse"
    assert me.resources[PULSE] == 0


def test_a_pool_no_trigger_generates_is_never_held():
    """Inert for everything that is not a trigger-generated pool: an ordinary Qi payment is untouched."""
    engine = _engine()
    me = engine.state.actors[ME]
    qi = next(rid for rid in me.resources if rid.endswith("qi"))
    engine._append_event("RESOURCE_GAINED", "test", actor_id=ME, target_ids=(ME,),
                         payload={"resource_id": qi, "gained": 1, "current": me.resources[qi] + 1})
    assert typed_reactions._holds(engine, me, qi, 1)


# ------------------------------------------------------------------------------- #2 a gain that gained nothing
def _lines(raw_events):
    from combat.gate2_engine import Gate2Engine

    engine = Gate2Engine(ROOT, match_seed="MMX116-LOG")
    rows = format_history_feed(raw_events, [], pre_state=None, post_state={},
                               actor_names={ME: "Tester"}, definition_names={})
    return [row.get("summary", "") for row in rows or []]


def test_the_log_does_not_claim_a_gain_that_gained_nothing():
    payload = {"resource_id": "resource:test.edict_seal", "requested": 1, "gained": 0, "current": 1}
    lines = _lines([{"event_type": "RESOURCE_GAINED", "actor_id": ME, "target_ids": [ME], "payload": payload}])
    assert not any("gained" in line for line in lines), lines

    payload = {"resource_id": "resource:test.edict_seal", "requested": 1, "gained": 1, "current": 1}
    lines = _lines([{"event_type": "RESOURCE_GAINED", "actor_id": ME, "target_ids": [ME], "payload": payload}])
    assert any("gained 1" in line for line in lines), lines
